pub fn MaxDifference(a: Vec<i32>) -> i32 {
    assert!(a.len() >= 2, "Input array must have at least two elements");

    // Initialize min and max with the first element
    let mut min_val = a[0];
    let mut max_val = a[0];

    // Traverse the rest of the array to find true min and max
    for &x in &a[1..] {
        if x < min_val {
            min_val = x;
        }
        if x > max_val {
            max_val = x;
        }
    }

    // The maximum difference between any two elements is max - min
    max_val - min_val
}

